"""SCOREBOARD.md, rendered from results/scoreboard.json and never typed by hand.

``craton check`` re-renders the board and fails if the Markdown differs from the JSON, so a
number can only reach the scoreboard through a benchmark run and the ratchet.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from craton.bench.catalog import BY_ID, CATALOG
from craton.bench.results import Scoreboard, ScoreEntry
from craton.paths import data_health_json, scoreboard_json, scoreboard_md

HEADER = (
    "<!-- Generated by `craton scoreboard` from results/scoreboard.json and\n"
    "     results/data_health.json. Do not edit by hand: `craton check` fails if this file\n"
    "     and the JSON disagree. -->\n"
)

ARROW = {"lower": "↓", "higher": "↑"}


def _num(x: float, fmt: str) -> str:
    return format(x, fmt).replace("-", "−")


def _fmt(entry: ScoreEntry) -> str:
    # Spread below a millionth of the score is floating-point noise, not a result.
    tiny = entry.std <= 1e-6 * max(1.0, abs(entry.mean))
    std = "0" if tiny else _num(entry.std, ".2g")
    return f"{_num(entry.mean, '.4g')} ± {std} {ARROW[entry.direction]}"


def _n(x: int) -> str:
    return f"{x:,}"


def _rejected(rejects: dict[str, int]) -> str:
    total = sum(rejects.values())
    if not total:
        return "0"
    top = sorted(rejects.items(), key=lambda kv: (-kv[1], kv[0]))[:2]
    return f"{_n(total)} ({', '.join(f'{k} {_n(v)}' for k, v in top)})"


def _says(name: str, health: dict[str, Any]) -> str:
    """One line on what an adapter's data holds, from its health entry."""
    if "seismic_catalog" in health:
        h = health["seismic_catalog"]
        big = h["largest"]
        types = ", ".join(f"{k} {_n(v)}" for k, v in h["magnitude_types"].items())
        mc_bits = []
        for mt, per_year in h["mc_per_year"].items():
            years = sorted(per_year)
            picks = [y for y in years if int(y) % 10 == 5] or years[:1]
            mc_bits.append(f"{mt} " + ", ".join(f"{per_year[y]:.1f} in {y}" for y in picks))
        mc_text = "; ".join(mc_bits)
        parts = [f"largest {big['type']} {round(big['magnitude'], 2):g} on {big['day']}", types]
        if mc_text:
            parts.append(f"completeness {mc_text}")
        if h["longest_gap_days"] is not None:
            parts.append(f"longest quiet spell {h['longest_gap_days']:g} days")
        return "; ".join(parts)
    if "gnss_daily" in health:
        h = health["gnss_daily"]
        return (
            f"{h['stations']} stations, median {_n(h['median_days_per_station'])} days each, "
            f"median coverage {h['median_coverage']:.0%}, {_n(h['gaps_over_30_days'])} gaps "
            "over 30 days"
        )
    if "solid_earth_tide" in health:
        h = health["solid_earth_tide"]
        pk = h["peak_m"]
        return (
            f"{_n(h['at_events'])} at earthquakes + {_n(h['hourly'])} hourly; peak "
            f"{pk['u']:.3f} m up, {pk['n']:.3f} m north, {pk['e']:.3f} m east"
        )
    return "·"


def _span(health: dict[str, Any]) -> str:
    h = next(iter(health.values()), None)
    if not h or h["first"] is None:
        return "·"
    return f"{h['first']} → {h['last']}"


def render_data(report: dict[str, Any] | None) -> list[str]:
    lines = ["", "## Data", ""]
    regions = (report or {}).get("regions", {})
    if not regions:
        lines.append("No data built yet. `craton data fetch` then `craton data build`.")
        return lines
    lines.append(
        "Measured on the latest build of each region by `craton data build`. The snapshot id is "
        "the hash of every token file, so it only changes if a byte of the data does."
    )
    for name in sorted(regions):
        r = regions[name]
        lines += [
            "",
            f"### {name} · snapshot `{r['snapshot']}` · {r['window'][0][:10]} → "
            f"{r['window'][1][:10]}",
            "",
            "| Source | Tokens | Span | Rejected | What it holds |",
            "|---|---|---|---|---|",
        ]
        for aname in sorted(r["adapters"]):
            a = r["adapters"][aname]
            lines.append(
                f"| `{aname}` | {_n(a['tokens'])} | {_span(a['health'])} | "
                f"{_rejected(a['rejects'])} | {_says(aname, a['health'])} |"
            )
    return lines


def best_baseline(board: Scoreboard, task_id: str) -> ScoreEntry | None:
    """The strongest simple method on a task: the floor a Craton model has to clear."""
    entries = list(board.baselines.get(task_id, {}).values())
    if not entries:
        return None
    sign = 1 if entries[0].direction == "higher" else -1
    return max(entries, key=lambda e: sign * e.mean)


def _floor(board: Scoreboard, task_id: str) -> str:
    entry = best_baseline(board, task_id)
    return f"{_fmt(entry)} · {entry.model}" if entry else "·"


def _gain(board: Scoreboard, task_id: str) -> str:
    """Craton vs the floor, in the task's own units (positive = Craton is better)."""
    entry, floor = board.entries.get(task_id), best_baseline(board, task_id)
    if not entry or not floor:
        return ""
    gain = entry.mean - floor.mean if entry.direction == "higher" else floor.mean - entry.mean
    return f" ({_num(gain, '+.3g')} vs {floor.model})"


def _notes(entry: ScoreEntry) -> str:
    """A task's telling secondary numbers, from the run's extras."""
    x = entry.extras
    if "M3.observed" in x:
        parts = [
            f"M≥3: {x['M3.observed']:,.0f} quakes, {x['M3.expected']:,.0f} expected",
            f"M≥1.5: {_num(x.get('M1.5.bits_per_eq', float('nan')), '.3g')} bits/quake",
            f"days with too few M≥3: {x['M3.days_too_few']:.0%}",
        ]
        return "; ".join(parts)
    if "rmse_east_mm" in x:
        return (
            f"east {x['rmse_east_mm']:.1f} · north {x['rmse_north_mm']:.1f} · up "
            f"{x['rmse_up_mm']:.1f} mm over {x['stations']:.0f} stations, "
            f"{x['station_days']:,.0f} days"
        )
    bits = [
        (k.split("_bits_per_token")[0], v) for k, v in x.items() if k.endswith("_bits_per_token")
    ]
    if bits:
        return " · ".join(f"{name} {v:.3g} bits" for name, v in sorted(bits))
    return ""


ORACLE_NAMES = {
    "count": "knowing each day's count",
    "where_10km": "knowing where, to ~10 km",
    "where_cell": "knowing where, to the cell",
    "roof": "the roof: count and cell",
}


def render_building(board: Scoreboard, building: dict[str, Any] | None) -> list[str]:
    """How far above ETAS a forecast can climb (``craton bench ceiling``), and where Craton
    and every forecast floor stand on it, in bits per M3+ quake above ETAS."""
    if not building:
        return []
    lines = [
        "",
        "## The building",
        "",
        "Bits per M3+ quake above ETAS. A forecast on floor k gives the real quakes 2^k times "
        "ETAS's probability. The oracles above ETAS read the answers; no method can, so they "
        "measure the room, not a target.",
        "",
        "| | " + " | ".join(sorted(building)) + " |",
        "|---|" + "---|" * len(building) + "",
    ]
    rows: list[tuple[str, list[str]]] = []
    for key in ("roof", "where_cell", "where_10km", "count"):
        rows.append(
            (
                f"oracle · {ORACLE_NAMES[key]}",
                [_num(building[t]["above_etas_bits"][key], "+.2f") for t in sorted(building)],
            )
        )
    methods: dict[str, list[str]] = {}
    for t in sorted(building):
        etas = building[t]["etas"]
        found = {f"{e.model} (floor)": e.mean for e in board.baselines.get(t, {}).values()}
        if t in board.entries:
            found[f"**Craton** · {board.entries[t].model}"] = board.entries[t].mean
        for name, mean in found.items():
            methods.setdefault(name, ["·"] * len(building))
            methods[name][sorted(building).index(t)] = _num(mean - etas, "+.2f")
    rows += sorted(methods.items(), key=lambda kv: -max(_value(v) for v in kv[1]))
    lines += [f"| {name} | " + " | ".join(vals) + " |" for name, vals in rows]
    return lines


def _value(cell: str) -> float:
    return float(cell.replace("−", "-")) if cell != "·" else float("-inf")


def render(
    board: Scoreboard,
    data: dict[str, Any] | None = None,
    building: dict[str, Any] | None = None,
) -> str:
    lines: list[str] = [HEADER, "# Scoreboard", ""]
    lines += [
        "Every number here comes from a script and is a mean ± std over 3 seeds. "
        "The ratchet only lets a number in if no other task gets worse beyond noise, "
        "so this table can only improve. The **floor** is the best simple method on each "
        "task: what a Craton model has to beat before it means anything.",
        "",
        "## Headline",
        "",
        "| | Task | Craton | Floor | Arrives |",
        "|---|---|---|---|---|",
    ]
    for task in (t for t in CATALOG if t.headline):
        entry = board.entries.get(task.task_id)
        now = _fmt(entry) + _gain(board, task.task_id) if entry else "not measured yet"
        lines.append(
            f"| **{task.name}** | {task.task_id} · {task.measures} | {now} | "
            f"{_floor(board, task.task_id)} | {task.phase} |"
        )

    lines += [
        "",
        "## Every task",
        "",
        "| ID | Task | Craton | Floor | Phase |",
        "|---|---|---|---|---|",
    ]
    known = {t.task_id for t in CATALOG}
    for task_id in sorted(known | set(board.entries) | set(board.baselines)):
        planned = BY_ID.get(task_id)
        entry = board.entries.get(task_id)
        name = planned.name if planned else task_id
        phase = planned.phase if planned else "—"
        score = f"{_fmt(entry)} · {entry.model}" if entry else "·"
        lines.append(f"| {task_id} | {name} | {score} | {_floor(board, task_id)} | {phase} |")

    lines += render_building(board, building)

    if board.baselines:
        lines += [
            "",
            "## The floor",
            "",
            "Simple methods, scored before any model exists. Each is ratcheted against itself.",
            "",
            "| Task | Method | Score | Metric | What else it says |",
            "|---|---|---|---|---|",
        ]
        for task_id in sorted(board.baselines):
            by = board.baselines[task_id]
            sign = 1 if next(iter(by.values())).direction == "higher" else -1
            for e in sorted(by.values(), key=lambda e: -sign * e.mean):
                lines.append(f"| {task_id} | {e.model} | {_fmt(e)} | {e.metric} | {_notes(e)} |")

    lines += ["", "## History", ""]
    if board.history:
        lines += ["| Accepted (UTC) | Run | Model | Ratchet |", "|---|---|---|---|"]
        for h in reversed(board.history):
            when = h.accepted.strftime("%Y-%m-%d %H:%M")
            who = f"{h.model} (baseline)" if h.kind == "baseline" else h.model
            lines.append(f"| {when} | `{h.run_id}` | {who} | {h.summary} |")
    else:
        lines.append(
            "No runs yet. The first real numbers are the simple baselines in P3, scored before "
            "any model exists, so the first model has something honest to beat."
        )
    lines += render_data(data)
    lines.append("")
    return "\n".join(lines)


def _load_data(root: Path) -> dict[str, Any] | None:
    path = data_health_json(root)
    if not path.is_file():
        return None
    out: dict[str, Any] = json.loads(path.read_text(encoding="utf-8"))
    return out


def _load_building(root: Path) -> dict[str, Any] | None:
    from craton.bench.ceiling import load

    return load(root / "results" / "ceiling.json")


def write(root: Path) -> Path:
    board = Scoreboard.load(scoreboard_json(root))
    out = scoreboard_md(root)
    out.write_text(
        render(board, _load_data(root), _load_building(root)), encoding="utf-8", newline="\n"
    )
    return out


def integrity_problem(root: Path) -> str | None:
    """None if SCOREBOARD.md is exactly what the JSON renders to."""
    md = scoreboard_md(root)
    if not md.exists():
        return "SCOREBOARD.md is missing. Run `craton scoreboard`."
    expected = render(
        Scoreboard.load(scoreboard_json(root)), _load_data(root), _load_building(root)
    )
    actual = md.read_text(encoding="utf-8").replace("\r\n", "\n")
    if actual != expected:
        return (
            "SCOREBOARD.md doesn't match results/scoreboard.json (edited by hand?). "
            "Run `craton scoreboard` to regenerate it."
        )
    return None
